ProjectALife.DialogueShards["scenes_any_30"] = {
{"s8_gang_four_four_103","any",2,"reg=gang|hour=21,23|mood=sad",{1,"Every night at ten I still punch four-four into Tone's pager number on the motel phone",2,"That phone ain't even got a dial tone",1,"I know, four-four means we good, he always hit back four-four",2,"What's the code for we ain't good?",1,"Never needed one"}},
{"s8_gang_water_tower_letters_104","any",3,"reg=gang|tmp=predator|day=3,3650|mood=funny",{1,"Painted our letters on the Muldraugh water tower last night - twelve feet tall",2,"Who's gonna read it?",1,"Anybody coming up 31W, they gonna know whose town this is",3,"Half the dead walking this town used to live here - they think it's their town",1,"Then they can start paying rent"}},
{"s8_gang_jump_in_roof_105","any",3,"reg=gang|day=5,3650|mood=grim|world=building,rooftop",{1,"Remember Shorty wanting to get jumped in?",2,"By who? Half the crew could barely stand",3,"You wanted him on watch instead, to prove he'd show up",1,"Wasn't how it used to go",3,"Nothing was how it used to go anymore"}},
{"s8_gang_counting_bag_106","any",2,"reg=gang|day=5,3650|mood=sad",{1,"Why you still counting that bag every night?",2,"Eleven thousand four hundred, two years on the corner",1,"Can't buy a stick of gum with it, man",2,"I know what it can't do - let me count",1,"And when you done?",2,"Start over, keeps my hands busy"}},
{"s8_gang_tick_leg_107","any",3,"reg=gang|day=2,120|mood=funny",{1,"Yo, there's a bug in my leg, it's in there - it's drinking",2,"That's a tick - hold still",3,"Burn it with a match, my uncle burned 'em off",1,"You not setting my leg on fire over a bug!",2,"Grown man hollering over a tick",1,"I watched a man's face come off Tuesday and didn't holler - this is different, this one's inside me"}},
{"s8_gang_deputy_gas_108","any",4,"reg=gang|day=5,3650|mood=angry",{1,"Deputy out at the Rosewood station wants to know which way the big crowd of them is heading",2,"We don't talk to police",3,"It's one deputy with a gas can, he ain't police no more - he's a man with a gas can",2,"Badge still on his shirt",4,"He trades gas for what we know - that's business, that ain't snitching",2,"Then you tell him, I'm not saying one word to no badge"}},
{"s8_gang_greens_on_109","any",2,"reg=gang|mood=sad|world=building",{1,"My grandmama's house is on Thirty-Fourth Street, plastic still on the couch",2,"You think she's there?",1,"She wasn't leaving, told me on the phone, said she had greens on",2,"Greens?",1,"Said it like it was a reason, greens on the stove, couldn't leave 'em"}},
{"s8_gang_fourteen_deal_110","any",2,"reg=gang|mood=warm|world=building",{1,"If a fourteen-year-old asked you for a gun, what would you say?",2,"You're fourteen",1,"They'd tell you fourteen is grown now. Look around",2,"I'd tell them I wanted them to reach fifteen. That's not a job you prove with a gun"}},
{"s8_gang_newburg_nurse_111","any",3,"reg=gang|day=3,3650|mood=calm",{1,"Newburg boys took the other end of the motel",2,"We had beef with Newburg since eighty-nine",3,"They got a nurse with 'em, worked the ER at University Hospital",1,"So what, we cool with Newburg now?",2,"We cool with the nurse - Newburg can stand behind her"}},
{"s8_gang_pickle_tab_112","any",2,"reg=gang|mood=warm",{1,"Mr. Harold at the corner store let us run a tab when we was little",2,"I took a pickle and a bag of chips on credit for three years",1,"You ever pay him?",2,"No, he never wrote nothing down, he just knew"}},
{"s8_gang_phone_hand_113","any",1,"reg=gang|role=gang_boss|mood=grim",{1,"Twenty soldiers on the first of the month, I made one call and a block shut down",1,"Now I make the call and the phone just sit there in my hand",1,"Seven left - seven's still a crew - seven's enough for a town this size"}},
{"s8_gang_popped_column_114","any",2,"reg=gang|day=5,3650|mood=funny|world=vehicle",{1,"Took me years to learn to pop a steering column in under a minute",2,"And now?",1,"Now the keys are hanging in every car in Muldraugh - every one, just sitting there",2,"Gas in 'em?",1,"Empty, whole county's a car lot where nothing starts"}},
{"s8_gang_church_court_115","any",3,"reg=gang|mood=funny|world=fence",{1,"Found a ball and a hoop behind the Baptist church - real rim - real net",2,"Can't dribble out here - sound carries",3,"We played one game to eleven, had eight of them watching from the fence by the end",1,"Better crowd than any game at Shawnee Park",3,"Crowd kept trying to come out on the court, though"}},
{"s8_gang_cardinals_jacket_116","any",2,"reg=gang|mood=fear",{1,"I remember one getting through a man's good Cardinals jacket",2,"Through the jacket? That jacket was thick",1,"Thick. That's what he kept telling himself",2,"Did he let anybody look?",1,"No. Kept it zipped. I think he was scared of what we'd say"}},
{"s8_gang_juice_debt_117","any",3,"reg=gang|tmp=predator|mood=angry|world=door",{1,"Juice still owes the crew two thousand from June",2,"Juice is dead, Twan",1,"Then his brother owes it",3,"His brother's fifteen and burning up with fever in the back room",1,"Debt's a debt",2,"Then go collect - go knock on that back room door and collect"}},
{"s8_gang_sophomore_shoes_118","any",2,"reg=gang|day=14,50|mood=sad",{1,"School was supposed to start in three weeks",2,"You worried about school?",1,"Not worried, I was gonna be a sophomore, had the shoes picked out",2,"What shoes?",1,"Don't matter, the white ones"}},
{"s8_gang_pickle_jar_porch_119","any",3,"reg=gang|mood=funny|world=door",{1,"Old lady on her porch looked at us like we was worse than the dead",2,"Pulled her screen door shut and locked it, a screen door",3,"Then she threw a jar of pickles at one of 'em coming up behind Boo",1,"Hit it square in the head - pickles everywhere",2,"And she still locked the screen door after"}},
{"s8_gang_rules_left_120","any",3,"reg=gang|mood=calm",{1,"New rule, nobody shoots unless there's no other choice. A shot could bring trouble we can't handle",2,"It's always life or death out here",1,"Then you better be sure it's yours",3,"What about the old rules?",1,"Old rules stand - nobody snitches, nobody steals from the crew - nobody gets left",2,"That last one's getting hard"}},
{"s8_gang_second_street_bridge_121","any",3,"reg=gang|day=1,90|mood=angry",{1,"You left Peanut at the Second Street bridge",2,"He was on the ground with four of 'em on him - what was I supposed to do?",1,"Something",3,"Leave him alone, Rico, he ran and he lived - that's something",1,"Peanut used to carry him home drunk - every time",2,"I know what Peanut did - I know"}},
{"s8_gang_quarter_phone_122","any",2,"reg=gang|mood=funny",{1,"Payphone out by the Irvington gas station, picked it up out of habit",2,"Dial tone?",1,"Nothing - put my quarter in anyway",2,"Get it back?",1,"No, phone company still robbing folks at the end of the world"}},
{"s8_gang_hydrant_creek_123","any",3,"reg=gang|day=0,70|hour=11,18|mood=funny|world=water",{1,"Back home we'd crack open the fire hydrant on a day like this",2,"No hydrants out here, they got a creek",3,"Creek's got snakes",1,"Hydrant didn't have snakes",2,"Hydrant had Five-O rolling up in ten minutes to shut it off",3,"I'll take the snakes"}},
{"s8_gang_laser_picture_124","any",2,"reg=gang|mood=sad",{1,"Only picture of my daughter I got is her school picture - the one with the lasers behind her",2,"She look like you?",1,"Looks like her mama, thank God, got my ears, though",2,"Where she at?",1,"With her mama - in Shively, I say that like I know"}},
{"s8_gang_corner_love_125","any",2,"reg=gang|mood=calm",{1,"Old head told me when I was twelve, the corner don't love you back",2,"He was right",1,"He was, corner's gone now - still don't love me",2,"Crew does - some days"}},
{"s8_gang_d_cells_126","any",3,"reg=gang|tmp=predator|day=10,3650|mood=funny|world=vehicle",{1,"Forget dope, batteries is the new work",2,"What's D-cells going for?",1,"Four of 'em gets you a box of shells or a bag of rice in Riverside",3,"We got a whole electronics store stockroom sitting in the van",1,"Then we the biggest dealers in Knox County, nobody lick the product"}},
{"s8_gang_smoke_shaking_127","any",3,"reg=gang|day=3,30|mood=grim|world=building",{1,"Smoke's been shaking in the bathroom three days",2,"Nothing coming down from Louisville no more, nothing coming from anywhere",3,"He gonna die from it?",2,"Probably not, he's gonna wish he did for about a week",1,"Somebody bring him water, and lock up the cough syrup"}},
{"s8_gang_do_not_disturb_128","any",3,"reg=gang|day=3,3650|mood=funny|world=door",{1,"Motel's got twenty-two rooms, we're in six of 'em",2,"What's in the rest?",3,"Guests, still checked in, them doors stay shut",1,"Hang a Do Not Disturb on every knob, this time we mean it"}},
{"s8_gang_where_you_from_129","any",2,"reg=gang|mood=sad|world=vehicle",{1,"Where you from?",2,"You know where I'm from, man",1,"I'm asking like old times, like on the bus - where you from?",2,"Portland, twenty-Sixth and Bank",1,"Russell - there, now we both said it out loud"}},
{"s8_gang_one_arm_grill_130","any",2,"reg=gang|mood=sad",{1,"Fourth of July at Chickasaw Park, my uncle had the grill going since six in the morning",2,"Your uncle with one arm?",1,"One arm, and he still flipped every rib himself, wouldn't let nobody touch that grill",2,"Them ribs was good",1,"Got sauce on my good shirt, I still got the shirt"}},
{"s8_gang_say_twelve_131","any",2,"reg=gang|day=3,3650|mood=grim",{1,"I did the math, twelve from the set since Friday",2,"You don't gotta count",1,"Somebody gotta, their mamas can't",2,"Then say 'em - all twelve - I'm listening"}},
{"s8_gang_cow_fryer_132","any",3,"reg=gang|day=7,3650|mood=funny",{1,"It's a cow, just standing there, that's a whole lot of burgers",2,"You know how to cut up a cow?",1,"No, you?",3,"I worked the fryer at the chicken place on Broadway two summers",2,"That's chicken, comes already cut",3,"I'm saying I'm the closest thing we got"}},
{"s8_gang_pink_collar_133","any",2,"reg=gang|mood=sad|world=vehicle",{1,"Trouble jumped out the van and went straight at 'em - all six, bought us the minute",2,"Whole block was scared of that dog",1,"She slept under my little sister's bed every night",2,"You get her collar?",1,"Yeah - Spiked one, my sister picked it out - it's pink"}},
{"s8_gang_officer_dunn_134","any",3,"reg=gang|mood=funny|world=vehicle",{1,"Never thought I'd say it, I kind of miss Five-O",2,"Man, what?",1,"You knew what they wanted, they wanted you in the car, these want you in their mouth",3,"Officer Dunn chased me down Broadway every Friday for a year - I'd let him catch me now, I'd let him"}},
{"s8_gang_blaze_orange_135","any",2,"reg=gang|mood=funny",{1,"Why you wearing a hunter orange vest?",2,"Country folks don't shoot at orange, orange means you a person",1,"You look like a traffic cone, man",2,"A traffic cone with no holes in it"}},
{"s8_gang_connect_chain_136","any",3,"reg=gang|day=2,90|mood=grim",{1,"Saw our connect by the Dixie Highway exit, still in his good suit - walking wrong",2,"He still owe us for that front?",1,"He owe everybody, he still got the gold chain on",3,"Go get it, then",1,"That chain's staying right where it is, I ain't collecting from that"}},
{"s8_gang_bible_latch_137","any",2,"reg=gang|day=3,3650|mood=warm",{1,"My sister went with the church people in Rosewood, said she ain't living with a gang",2,"She said it like that?",1,"To my face, then she hugged me and put a Bible in my bag",2,"You read it?",1,"It's holding the ammo box lid shut, I'll read it when I fix the latch"}},
{"s8_gang_fresh_ones_run_138","any",3,"reg=gang|mood=fear",{1,"Nee-Nee says some of 'em run",2,"Nee-Nee says a lot of stuff",3,"I said the fresh ones run, the ones just turned, like their legs still remember",1,"How long they remember?",3,"Long enough to catch Scooter"}},
{"s8_gang_little_league_139","any",2,"reg=gang|mood=funny",{1,"All them years on the block, everything was about the strap",2,"Strap's the loudest thing in this county",1,"Now I'm walking around with a wood bat like I'm back in Little League",2,"How'd you do in Little League?",1,"Struck out every game, every single game",2,"Well, you ain't missing now"}},
{"s8_gang_lookout_boss_140","any",3,"reg=gang|day=3,3650|mood=angry",{1,"Dre calling shots like he Big Mike now",2,"Big Mike ain't here",1,"That's my point - Dre was a lookout in June - a lookout",3,"Lookout's the one who saw it coming, only one of us who got his little brother out",1,"So he's the boss for having eyes?",3,"He's the boss for using 'em"}},
{"s8_gang_stitch_cuss_141","any",3,"reg=gang|day=3,3650|mood=funny",{1,"Newburg nurse sewed up my arm - eleven stitches",2,"What she charge?",1,"Says I owe her a clean mouth, every time I cuss around her, she's taking a stitch back out",3,"Then you owe her four already, just telling this story"}},
{"s8_gang_scissor_fade_142","any",3,"reg=gang|day=10,3650|mood=funny",{1,"Hold still, I'm doing a fade with scissors and a comb - no clippers",2,"Man, you gonna mess up my line",1,"Who's gonna see your line?",3,"God gonna see it, do it right, Pooh",1,"Then God can hold the mirror"}},
{"s8_gang_static_beat_143","any",2,"reg=gang|day=3,3650|mood=sad",{1,"Kev keeps turning the dial looking for his station out of Louisville",2,"It's gone, static since the second night",1,"He knows, says the static got a beat in it if you listen long enough",2,"Does it?",1,"I been listening - kinda"}},
{"s8_gang_pages_lane_144","any",3,"reg=gang|day=0,30|mood=fear|world=vehicle,road",{1,"We came down Dixie Highway with the headlights off, pushing ninety",2,"Man stepped out in the road at Pages Lane, just stepped right out",3,"Wasn't a man",2,"I know it wasn't, windshield still got the star in it"}},
{"s8_gang_cornbread_counts_145","any",3,"reg=gang|tmp=predator|day=7,3650|mood=funny",{1,"Trailer park in Irvington pays us in food now, two cans a trailer, every Sunday",2,"What they get for it?",1,"Nobody else robs 'em, and we put down the dead ones at the gate",3,"Lady in number nine paid in cornbread",1,"Cornbread counts - tell her it counts double"}},
{"s8_gang_hand_ink_146","any",2,"reg=gang|mood=grim",{1,"Church folks saw the ink on my hand and wouldn't let me in their gym",2,"Ink says what it says",1,"Ink says Portland, that's a neighborhood, that's where my mama lived",2,"They don't know that, they know what they heard on the six o'clock news"}},
{"s8_gang_ice_cream_truck_147","any",3,"reg=gang|mood=fear|world=vehicle",{1,"Ice cream truck on the shoulder, keys in it",2,"Anything inside?",1,"Freezer full of melted everything, smells like a birthday party died in there",3,"Does it start?",1,"It starts, and the music box comes on and won't shut off",2,"Leave it, leave it right there"}},
{"s8_gang_ray_ray_bat_148","any",2,"reg=gang|mood=grim",{1,"Little man had to do his boy Ray-Ray, friends since second grade",2,"He say anything about it?",1,"Only thing he said was he used Ray-Ray's own bat - so Ray-Ray wouldn't mind"}},
{"s8_gang_friday_envelope_149","any",2,"reg=gang|day=7,3650|mood=warm",{1,"It's Friday - Friday was payday",2,"Payday in what?",1,"I'm just saying, every Friday Big Mike came through with the envelopes",2,"Here - envelope, it's a can of peaches",1,"Best payday I had all month"}},
{"s8_gang_roof_mutter_150","any",1,"reg=gang|hour=20,5|mood=fear|world=building,rooftop,road",{1,"Stay on the roof, they said, watch the road - shoot anything that ain't us",1,"What if it is us? What if it's Tone walking up that road? What am I supposed to do then?",1,"Shoot it, I guess, shoot it and tell 'em it wasn't nobody"}},
{"s8_gang_okolona_truck_151","any",3,"reg=gang|day=3,90|mood=angry|world=vehicle",{1,"Okolona boys want to run with us",2,"Same boys jumped Rico outside Bashford Manor mall in ninety-one?",3,"Same boys, now there's three of 'em and one's got a busted foot",1,"They got a pickup with a full tank",2,"Rico decides",3,"Rico says the truck can come, the boys can walk behind it"}},
{"s8_gang_shoulder_box_152","any",2,"reg=gang|mood=sad",{1,"Carried that box on my shoulder from Portland all the way to Muldraugh",2,"It don't even play, you got no batteries",1,"I know",2,"So why carry twenty pounds of nothing?",1,"Last thing I own that I paid for"}},
{"s8_gang_dice_shifts_153","any",3,"reg=gang|hour=18,2|mood=funny|world=building",{1,"Seven - pay me",2,"Pay you what? We shooting for watch shifts",1,"Then you got my Tuesday",3,"He's got your Tuesday, my Wednesday and Boo's whole weekend",2,"I'm gonna be on that roof till Christmas",1,"Should've walked when you was up"}},
{"s8_gang_cooler_pills_154","any",4,"reg=gang|tmp=predator|mood=angry",{1,"Somebody took the pills out the cooler",2,"Never touched it",3,"Me neither, man",4,"Nobody touched nothing, so everybody empty your pockets on the hood",1,"Whoever it was gets one night to put 'em back - after that it ain't a question no more"}},
{"s8_gang_purple_hat_155","any",2,"reg=gang|mood=warm|world=vehicle",{1,"Why you dragging that hat around?",2,"Mama's church hat, the purple one with the feather",1,"It's getting crushed in that bag",2,"She used to pop me with it for talking during service - right here - feather first",1,"Put it up on the dashboard, then, where it can breathe"}},
{"s8_gang_three_hundred_yards_156","any",2,"reg=gang|day=5,3650|mood=funny|world=building,road",{1,"Farmer's rifle hits where you point it from three hundred yards",2,"What I need three hundred yards for? Everything on the block was across the street",1,"Out here across the street is a mile",2,"Then this whole county's across the street, and every porch got a rifle on it"}},
{"s8_gang_kids_in_fire_157","any",3,"reg=gang|day=3,60|mood=angry|world=water",{1,"Last I heard, my kids were in the city. I keep thinking about going back",2,"I've heard awful things. Doesn't mean I know what's waiting there",1,"Doesn't tell me where my kids are either",3,"Let him go",2,"I'd want him to check what he could take and how he'd get back",3,"And ask for help before he leaves. Don't send him off with promises we can't back up"}},
{"s8_gang_can_labels_158","any",2,"reg=gang|mood=warm|world=vehicle",{1,"What's that one say?",2,"P... peas",1,"And that one?",2,"Car... carrots, I ain't stupid - I just never went much",1,"Didn't say stupid, said read the next can"}},
{"s8_gang_gas_deed_159","any",3,"reg=gang|tmp=predator|day=7,3650|hour=16,5|mood=angry|world=vehicle",{1,"Raiders out of West Point parked a truck at our gas station",2,"Our gas station? Since when do we own a gas station?",1,"Since we cleared every dead thing out that lot and hand-pumped the tank - that's a deed",3,"They got four rifles on that truck",1,"Then we come back tonight with five"}},
{"s8_gang_jv_jerseys_160","any",3,"reg=gang|day=5,3650|mood=funny",{1,"Found a box of basketball jerseys at the high school - all the same color",2,"So now we look like a team",3,"Says Junior Varsity on the back, every one of 'em",1,"Wear it, nobody shoots at JV - nobody even hates JV"}},
{"s8_gang_god_counting_161","any",2,"reg=gang|mood=sad",{1,"Man-Man asked me if Big Mike went to heaven, with everything he done",2,"What you tell him?",1,"Told him Mike carried three kids out of Cotter Homes on his back - God was probably counting",2,"Was He?",1,"I don't know, I would've counted"}},
{"s8_gang_park_hill_boo_162","any",2,"reg=gang|tmp=predator|mood=grim|world=building",{1,"Saw Lil Boo from Park Hill today, the one who shot my cousin",2,"You do him?",1,"Somebody beat me to it, he was sitting against the wall of the dollar store - done",2,"How you feel?",1,"Cheated, then something else - then cheated again"}},
{"s8_gang_bow_soup_163","any",3,"reg=gang|day=3,3650|mood=funny",{1,"Pastor at the Rosewood food line made us bow our heads before he'd pour the soup",2,"You bowed?",1,"Bowed, one eye open and one hand on the strap",3,"Soup was good, though",1,"Soup was real good, I might go back and bow some more"}},
{"s8_gang_blink_code_164","any",3,"reg=gang|hour=20,5|mood=calm|world=vehicle,building,rooftop",{1,"Flashlight from the roof, one blink, all good, two, something's coming, three, everybody to the van",2,"What's four?",1,"Ain't no four",3,"What if it's people coming? Not them - people",1,"Then two blinks, and you keep the light on 'em so they know we see 'em"}},
{"s8_gang_ice_machine_165","any",3,"reg=gang|mood=funny|world=vehicle,door",{1,"Nee-Nee put down three of 'em with a tire iron while you was hiding in the ice machine",2,"I was not in the ice machine, I was next to the ice machine",3,"You was in it, your shoes was sticking out the door",1,"From now on Nee-Nee picks who goes on runs",2,"Fine, pick me, I'll show you",3,"Ice machine's still there if you need it"}},
{"s8_gang_shake_him_166","any",2,"reg=gang|mood=sad",{1,"Listen, the stash is under the ice chest in room four - split it even - even",2,"Stop talking like that, nurse is coming",1,"And watch my nephew, he's slow getting up in the morning - don't holler at him, just shake him",2,"Stop it",1,"Just shake him, man - that's all"}},
{"s8_gang_man_in_tie_167","any",2,"reg=gang|day=2,3650|mood=funny",{1,"Last thing on the motel TV was a man in a tie saying stay in your homes",2,"We was in a motel",1,"So we did what he said - Motel's home now",2,"Worst home I ever had, and I lived over a laundromat with a hole in the floor"}},
{"s8_gang_dairy_name_168","any",3,"reg=gang|day=7,3650|mood=funny",{1,"Country kid we picked up needs a name",2,"What's his real name?",3,"Dwight",1,"We can't have a Dwight",2,"He milked that cow by himself - call him Dairy",3,"My name's Dwight",1,"Not no more, Dairy"}},
{"s8_gang_ring_out_of_it_169","any",3,"reg=gang|day=5,3650|mood=grim",{1,"A man in Riverside once offered a rifle and his wife's ring for pain pills",2,"What did you do?",3,"His wife had been bitten. He was desperate to stop her hurting",2,"You still wanted the rifle?",3,"I told myself I was leaving the ring out of it",1,"But not the rifle?",3,"I took the rifle. I ain't a saint"}},
{"s8_gang_rain_knocking_170","any",2,"reg=gang|hour=19,5|mood=calm|world=building,rain",{1,"Rain on a tin roof, sounds like my grandmama's back porch",2,"Sounds like somebody knocking",1,"It ain't",2,"I know, still sounds like it"}},
{"s8_gang_country_set_171","any",2,"reg=gang|mood=funny",{1,"Why'd you throw up the set at that farmer?",2,"Habit, he was mean-mugging me",1,"He waved back",2,"He waved with a shotgun",1,"That's a country set, we don't want no beef with that set"}},
{"s8_gang_cowboy_coffee_172","any",2,"reg=gang|hour=5,10|mood=warm",{1,"Who made coffee?",2,"Miss Loretta from room eleven, boiled it in a pot with the grounds right in it",1,"It's full of grounds",2,"She says strain it through your teeth",1,"It's good, though",2,"Don't tell her, she'll start charging"}},
{"s8_gang_deuce_ditch_173","any",4,"reg=gang|tmp=predator|day=7,3650|mood=angry|world=road",{1,"West Point raiders knew exactly when we left the motel yesterday",2,"Somebody told 'em",3,"Deuce been walking out to the road every night, says he's using the ditch",4,"Nobody uses a ditch for forty minutes",1,"Bring Deuce, bring him and a shovel",2,"Shovel for what?",1,"He's gonna dig while he talks"}},
{"s8_gang_calling_marcus_174","any",2,"reg=gang|hour=19,23|mood=fear|world=road",{1,"You hear that? Lady calling a name out in the dark",2,"Calling who?",1,"Sounds like Marcus, over and over, same way my mama called us in off the street",2,"Want to go look?",1,"Nah, I hear it every night - every night it's a little closer to our end of town"}},
{"s8_gang_squeak_shoes_175","any",2,"reg=gang|mood=funny",{1,"Your shoes squeak - every step, like a gym floor",2,"They new, got 'em out the shoe store in Muldraugh",1,"Then they gonna get you killed brand new",2,"Least I'll look good",1,"Rub mud on 'em - be quiet and ugly"}},
{"s8_gang_list_crossed_176","any",2,"reg=gang|tmp=predator|day=10,3650|mood=grim",{1,"Had a list in my head, everybody who crossed me since I was fifteen",2,"How many left on it?",1,"None, every name crossed off, I didn't do a single one of 'em",2,"So you won",1,"Don't feel like winning, feels like I got stood up"}},
{"s8_gang_sit_where_he_sees_177","any",3,"reg=gang|hour=22,5|mood=sad",{1,"Man-Man woke up screaming again",2,"Tell him hush - sound carries",3,"I'll sit with him, I woke up the same way for a year after my brother got shot",2,"What you gonna tell him?",3,"Nothing, you don't tell 'em nothing - you just sit where they can see your shoes"}},
{"s8_gang_bus_pass_178","any",2,"reg=gang|day=2,20|mood=sad|world=vehicle",{1,"Still got my monthly bus pass in my wallet, paid through July",2,"Gonna catch a bus?",1,"Number eighteen, rode it every morning with my little brother to his school",2,"Keep the pass",1,"I'm keeping it, it's still good for thirteen more days"}},
{"s8_gang_knock_nobody_179","any",3,"reg=gang|mood=funny",{1,"Knock knock",2,"Man, don't",1,"Knock knock!",3,"Who's there?",1,"Nobody - nobody's there, nobody's anywhere, hahaha!",3,"That ain't even a joke",1,"It was funnier in my head"}},
{"s8_gang_filthy_nine_180","any",2,"reg=gang|mood=calm",{1,"Your nine is filthy - When's the last time you cleaned it?",2,"Never, never had to - never shot it this much",1,"It jams on you out there, you ain't gonna get another chance to clean it",2,"Show me, then",1,"Sit down, spring comes out first - don't let it fly across the room"}},
{"s8_gang_pool_laundry_181","any",2,"reg=gang|day=5,3650|mood=funny",{1,"You used to volunteer for the Newburg side of that motel",2,"I was being neighborly",1,"With the girl who washed clothes in the pool?",2,"She had water, I had dirty clothes. Called it logistics"}},
{"s8_gang_sit_on_gold_182","any",3,"reg=gang|mood=funny",{1,"Fort Knox is right there, all that gold, and no police nowhere",2,"Army's still there - with tanks",1,"Tanks need gas too",3,"And say you get the gold - then what? You gonna eat a bar of it?",1,"I'm gonna sit on it - one time, just to say I sat on it"}},
{"s8_gang_lagrange_brother_183","any",2,"reg=gang|mood=sad|world=door",{1,"My brother's doing six years up at LaGrange",2,"You think they let 'em out?",1,"Either they let 'em out or they locked the doors and left",2,"Maybe he's out",1,"He always said he'd do every day and walk out the front gate - four years left - he'd wait"}},
{"s8_gang_look_like_her_boys_184","any",2,"reg=gang|day=14,3650|mood=warm",{1,"Lady from number nine brought us beans and cornbread, didn't ask for nothing",2,"We shake her down every Sunday",1,"I know",2,"Then why's she feeding us?",1,"Said we look like her boys"}},
{"s8_gang_warning_shots_185","any",2,"reg=gang|mood=funny",{1,"South End boys can't shoot - Shane emptied a whole clip at one standing still",2,"I was warning it",1,"Seventeen warning shots",2,"And it got the message"}},
{"s8_gang_count_off_186","any",3,"reg=gang|hour=5,9|mood=fear|world=window,building",{1,"Count off",2,"One",3,"Two",1,"Three's me - where's four? Where's Kev at?",2,"His blanket's still warm",3,"Bathroom window's open"}},
{"s8_gang_rice_glue_187","any",2,"reg=gang|mood=funny",{1,"How much water for rice?",2,"Enough",1,"How much is enough?",2,"My mama never measured, she just looked at it",1,"Well, I'm looking at it, and it's looking back at me like glue"}},
{"s8_gang_stars_188","any",2,"reg=gang|hour=21,4|mood=calm",{1,"Look up, man",2,"What?",1,"Stars, that's all stars - never seen that many in my life",2,"They was always there, city was just too bright",1,"City ain't bright no more"}},
{"s8_gang_boss_scared_mutter_189","any",1,"reg=gang|role=gang_boss|mood=fear|world=window",{1,"Can't let 'em see me scared, first time they see it, it's over",1,"Mike never looked scared - not once, not when they shot out the windows on Thirty-Eighth",1,"Maybe he was, maybe he was just better at hiding it than me"}},
{"s8_gang_tile_bathroom_190","any",2,"reg=gang|mood=funny|world=building",{1,"What?",2,"I said you shot it inside the bathroom - inside, all that tile",1,"What?",2,"Forget it, you'll hear me Thursday"}},
{"s8_gang_wall_map_191","any",3,"reg=gang|day=5,3650|hour=16,5|mood=calm|world=door",{1,"Motel's here, gas station's ours - Grocery's theirs, past the tracks is all dead folks",2,"What about the school?",1,"School's nobody's, too many doors",3,"Draw a line at the tracks, anybody crosses it after dark ain't friendly",2,"Even Newburg?",3,"Newburg knocks first"}},
{"s8_gang_handshake_snap_192","any",2,"reg=gang|mood=sad",{1,"Do the handshake before you go",2,"Man, we ain't twelve",1,"Do it, all the way through - the snap at the end",2,"Why?",1,"Because Tone left without doing it"}},
{"s8_gang_fried_bologna_193","any",2,"reg=gang|mood=funny",{1,"What you miss most?",2,"Fried bologna - white bread - mustard - cut the edge so it don't bubble up",1,"That's it? Not your girl? Not your ride?",2,"My girl left in May, my ride got repossessed in June - bologna never did me like that"}},
{"s8_gang_grave_fishing_194","any",3,"reg=gang|day=7,3650|mood=calm|world=water",{1,"Old man with the shotgun wants somebody to walk him to his wife's grave Sunday",2,"What's he paying?",1,"Says he'll teach whoever goes how to fish the river",3,"I'll walk him",2,"You hate fish",3,"I hate starving more"}},
{"s8_gang_four_months_shoes_195","any",2,"reg=gang|tmp=predator|mood=grim",{1,"Them Tone's shoes?",2,"He'd want somebody wearing 'em",1,"He'd want 'em back, he saved four months for them shoes",2,"Then he can come get 'em"}},
{"s8_gang_bad_saturday_196","any",3,"reg=gang|day=5,3650|mood=grim",{1,"Inventory, two nines, one forty-five, the sawed-off, the farmer's deer rifle",2,"Rounds?",1,"Thirty-one nine, six for the forty-five - eleven shells, twenty for the rifle",3,"That's a bad Saturday night on Broadway",1,"That's all of it, for all of us - for good"}},
{"s8_gang_bmx_scout_197","any",2,"reg=gang|mood=warm",{1,"Man-Man scouts on that little BMX - quiet as anything",2,"He fast?",1,"He's twelve and scared, ain't nothing in this county faster than that"}},
{"s8_gang_two_dudes_198","any",2,"reg=gang|day=45,3650|mood=sad",{1,"Just us two now",2,"Still a crew",1,"Two ain't a crew, two is a couple of dudes",2,"Then we the best couple of dudes in Knox County",1,"We the only couple of dudes in Knox County"}},
{"s8_gang_menthol_rub_199","any",2,"reg=gang|day=3,40|mood=grim",{1,"Whole town smells like a dumpster behind a fish market",2,"Put some chest rub under your nose",1,"Did, now it smells like a dumpster with a cold"}},
{"s8_gang_know_my_name_mutter_200","any",1,"reg=gang|tmp=predator|mood=angry",{1,"Everybody I ever had beef with is dead, everybody I ever loved is dead",1,"And the only thing still wants a piece of me don't even know my name",1,"On the block, at least, they knew my name"}},
{"s8_crime_shine_fuel_201","any",3,"reg=crime|day=7,3650|mood=funny|world=vehicle",{1,"Hundred and ninety proof off the second doubling, that'll run a truck if you rejet the carburetor",2,"You're gonna pour Papaw's recipe in a gas tank?",1,"Papaw's recipe is the corn, I'm just leaving out the part that tastes like anything",3,"Club boys'll pay whatever we ask, they're pushing bikes up hills",2,"Papaw would roll over in his grave",1,"Papaw's grave is in the side yard, if he rolls, I'll see it"}},
{"s8_crime_last_sugar_202","any",2,"reg=crime|day=20,3650|mood=grim|world=building",{1,"Last sack of sugar in the county is sitting in that church pantry",2,"Then we go back to straight corn, like before sugar got cheap",1,"Straight corn takes twice as long and gives half",2,"Everything takes twice as long and gives half now - get the malt sprouting"}},
{"s8_crime_opal_back_door_203","any",2,"reg=crime|mood=funny",{1,"Forty years this county voted dry, forty years Aunt Opal sold beer out her back door on Sundays",2,"Law never shut her down",1,"Sheriff was her best customer, pint of peach every Friday",2,"Who's buying now?",1,"Same folks, they pay in eggs and bandages"}},
{"s8_crime_ninety_days_204","any",2,"reg=crime|day=14,3650|mood=sad",{1,"Pawn book's got forty-one open tickets, due dates all through July and August",2,"Nobody's coming in to pay 'em off",1,"Doris Whitt pawned her wedding ring for a transmission, came in every month to pay the interest",2,"She coming this month?",1,"Store policy is ninety days past due, I'm giving her the ninety"}},
{"s8_crime_best_crop_205","any",3,"reg=crime|day=0,60|mood=grim",{1,"Two hundred plants on the ridge behind the Ekron church - sixty days out from harvest",2,"Who's gonna buy it? Louisville's gone",3,"Folks with a bite and a long night ahead of 'em - that's who",1,"Best crop I ever put in the ground - figures"}},
{"s8_crime_chopper_wave_206","any",2,"reg=crime|day=1,90|hour=4,11|mood=funny",{1,"Helicopter come over the ridge low this morning",2,"State police?",1,"Army, didn't even slow down over the patch",2,"Twelve years I hid from helicopters, now I stand in the field and wave, and they don't look down"}},
{"s8_crime_pawn_fort_207","any",3,"reg=crime|mood=calm|world=door,window",{1,"Bars on the windows, steel on the door, sixty guns behind the counter",2,"Every pawn shop's a fort - Merle always said it'd come in handy one day",3,"Merle said that about the cash register too",1,"So Merle was half right"}},
{"s8_crime_bass_boat_208","any",3,"reg=crime|day=7,3650|mood=angry",{1,"Cecil owes me six hundred dollars from April",2,"Six hundred dollars don't buy a candle",1,"Then he owes me six hundred dollars of something",3,"What's six hundred dollars of something?",1,"His bass boat, and the trailer"}},
{"s8_crime_honest_bead_209","any",2,"reg=crime|mood=warm",{1,"Shake the jar - watch the bubbles",2,"They're big, they're sitting up on top",1,"That's a good bead, that's over a hundred, your granddaddy'd call that honest",2,"What's dishonest look like?",1,"Little bubbles that run off quick, like the man selling it"}},
{"s8_crime_drunk_hogs_210","any",2,"reg=crime|mood=funny",{1,"Hogs are drunk again",2,"You fed 'em the spent mash?",1,"They love it, laying out in the pen hollering",2,"Drunk hogs hollering all night pulls in every dead thing in the holler",1,"Then that's the best alarm in Knox County, it's just drunk"}},
{"s8_crime_car_stereos_211","any",2,"reg=crime|day=7,3650|mood=funny|world=vehicle",{1,"Four hundred car stereos - pull-out decks, every one, took me three years to fill that garage",2,"What's that worth now?",1,"Traded one for a chicken yesterday",2,"A live one?",1,"Live one - she lays, so I'm up on the deal"}},
{"s8_crime_can_line_212","any",2,"reg=crime|mood=calm",{1,"Them cans on fishing line around the patch, strung 'em for deer and nosy kids",2,"Work on the dead?",1,"Better - deer learn, the dead walk into it every night, rattling like a tambourine",2,"And you come running",1,"With the flat shovel - every night"}},
{"s8_crime_papaw_rules_213","any",3,"reg=crime|day=5,3650|mood=calm",{1,"Papaw had three rules - don't sell to children, don't water the jar, and don't talk to a revenue man",2,"Ain't no revenue men left",3,"Ain't no children buying, neither",1,"Then that's one rule left, and I aim to keep it"}},
{"s8_crime_pocket_watch_214","any",2,"reg=crime|day=2,3650|hour=16,22|mood=sad|world=door,road",{1,"That Friday afternoon we had a line out the door - rings, rifles, a set of golf clubs",2,"Everybody wanted gas money to get out",1,"Paid a man fifty dollars for his daddy's pocket watch - he cried at the counter",2,"Did he get clear of the county?",1,"His car's still in the lot across the street, they shut the roads at sundown"}},
{"s8_crime_logging_roads_215","any",3,"reg=crime|mood=calm|world=road",{1,"Army's got 31W, got the bridge, got every main road toward Fort Knox",2,"They ain't got the logging roads",3,"Daddy ran liquor down them logging roads with the headlights off in nineteen sixty-two",1,"You can still find 'em?",3,"I can find 'em drunk or blind, done it both ways since I was twelve"}},
{"s8_crime_pole_beans_216","any",2,"reg=crime|day=20,3650|mood=funny",{1,"Pulled up half the plants and put in pole beans",2,"You cried, didn't you?",1,"I did not cry, got pollen in my eye",2,"Pole beans",1,"Don't say it like that, they're good beans"}},
{"s8_crime_price_board_217","any",2,"reg=crime|day=10,3650|mood=funny",{1,"New price board, box of nine millimeter, three cans of meat",2,"What's a diamond tennis bracelet go for?",1,"Half a can of meat",2,"Half?",1,"And I'm being generous, I want the whole can"}},
{"s8_crime_honey_mash_218","any",3,"reg=crime|day=20,3650|mood=warm",{1,"Beekeeper up at March Ridge'll trade honey for a case of jars",2,"Honey mash, that's near about mead",3,"Papaw'd call it sissy liquor",1,"Papaw drank it at my cousin's wedding and danced with the preacher's wife",3,"That was the honey talking, then"}},
{"s8_crime_tackett_worm_219","any",3,"reg=crime|day=5,3650|mood=angry",{1,"Tackett boys come over the ridge and took our copper worm",2,"Tacketts, fifty years of this",3,"Their still blew up Tuesday, no copper, they got nothing to trade for food",1,"So they steal ours",2,"Go get it back, and take 'em a sack of corn, a starving Tackett's worse than a thieving one"}},
{"s8_crime_no_number_mutter_220","any",1,"reg=crime|day=5,3650|hour=4,11|mood=sad",{1,"Forty years behind this counter, I know what every single thing in this county is worth",1,"Guns, rings, TVs, chainsaws - give me ten seconds and I'd have a number",1,"Woman brought in a little girl's shoe this morning and asked what I'd give - I couldn't say a number"}},
{"s8_crime_cured_of_sober_221","any",2,"reg=crime|mood=fear",{1,"Dog bit me, least I'm pretty sure it was a dog, hahaha - poured shine on it and drank the rest",2,"Shine don't cure nothing but sober",1,"Then I'm cured of that much",2,"Show me the bite",1,"Pour me another one first"}},
{"s8_crime_tobacco_barn_222","any",3,"reg=crime|day=60,160|mood=fear|world=road",{1,"I remember a crop hanging in an old tobacco barn. Smelled it from the road",2,"Half a mile off the Ekron turn, I remember",3,"We worried somebody else might smell it too",1,"Could never tell how much of our worrying was about the crop and how much was about people"}},
{"s8_crime_teach_fire_223","any",2,"reg=crime|mood=warm",{1,"Your girl wants to learn the still",2,"She's fifteen",1,"I was eleven, you were ten",2,"And look at us",1,"Look at us - still here, teach her the fire first"}},
{"s8_crime_earl_chainsaw_224","any",2,"reg=crime|day=3,3650|mood=grim|world=door",{1,"That's Earl Bishop at the front door, pawned his chainsaw every November, bought it back every April",2,"Want to let him in?",1,"No, his chainsaw's still in the back, though",2,"Guess he ain't buying it back this April"}},
{"s8_crime_club_pound_225","any",3,"reg=crime|day=30,3650|mood=angry",{1,"Club says we owe 'em a pound for watching the patch all summer",2,"Watching it from who? From themselves?",3,"From everybody, from them things too - they lost a prospect up on that ridge",2,"Pay 'em half, then",1,"Pay 'em the whole pound, and a jar for that boy's grave"}},
{"s8_crime_two_rubber_bands_226","any",2,"reg=crime|day=10,3650|mood=funny",{1,"We got two hundred jars and eleven lids",2,"Plastic wrap and a rubber band",1,"On liquor?",2,"On the good liquor, two rubber bands"}},
{"s8_crime_sheriff_envelope_227","any",2,"reg=crime|day=10,3650|mood=grim",{1,"Twenty years I paid Sheriff Collins a hundred a month to look the other way",2,"And now?",1,"Saw him on Main Street yesterday, looking every which way",2,"You still owe him for July?",1,"Left it in an envelope on his porch, first of the month - habit"}},
{"s8_crime_rifle_wall_228","any",3,"reg=crime|day=2,30|mood=grim|world=building",{1,"Sold every rifle on the wall by Saturday noon, tripled the price and they paid it",2,"Made a killing",3,"Don't you say that word",2,"Figure of speech",1,"Wasn't a figure of speech for all of 'em"}},
{"s8_crime_deacon_tooth_229","any",3,"reg=crime|day=5,3650|mood=funny|world=door",{1,"Deacon Hollis came round the back door for a jar",2,"Deacon Hollis? He preached against us every Easter",1,"Said it's for his wife's toothache",3,"His wife passed in eighty-nine",1,"Then I reckon it's for her memory"}},
{"s8_crime_corner_post_230","any",2,"reg=crime|hour=17,21|mood=sad|world=fence",{1,"Junior's dog still walks the fence line at the patch every evening - same way Junior walked it",2,"Nobody taught him that",1,"Junior did, every evening for six years",2,"Feed him at the corner post, then, that's where Junior stopped to smoke"}},
{"s8_crime_bring_corn_231","any",4,"reg=crime|day=7,3650|mood=fear",{1,"West Point raiders want a case a week, or they burn the still",2,"A case a week is all we make",3,"Then we make two",4,"On what corn?",1,"On their corn - tell 'em if they want liquor, bring corn - Papaw made everybody that deal"}},
{"s8_crime_diamond_carpet_232","any",3,"reg=crime|day=5,3650|mood=funny",{1,"Jewelry store in West Point, no alarm, no law, no glass left in the cases",2,"Diamonds?",3,"Diamonds all over the carpet, nobody's picked 'em up",1,"Why not?",3,"What's a diamond do? Don't shoot, don't burn, can't eat it",2,"Get the watches, at least a watch tells time"}},
}
